const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Dubai', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date());
const get = (type) => parts.find((part) => part.type === type)?.value;
const date = `${get('year')}-${get('month')}-${get('day')}`;
return [{ json: { report_type: 'daily', from_date: date, to_date: date, period_label: date } }];

const pad = (value) => String(value).padStart(2, '0');
const fmt = (date) => `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Dubai' }));
const end = new Date(now);
const start = new Date(now);
start.setDate(end.getDate() - 6);
return [{ json: { report_type: 'weekly', from_date: fmt(start), to_date: fmt(end), period_label: `${fmt(start)} إلى ${fmt(end)}` } }];

const pad = (value) => String(value).padStart(2, '0');
const fmt = (date) => `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Dubai' }));
const firstThisMonth = new Date(now.getFullYear(), now.getMonth(), 1);
const lastPrevMonth = new Date(firstThisMonth);
lastPrevMonth.setDate(0);
const firstPrevMonth = new Date(lastPrevMonth.getFullYear(), lastPrevMonth.getMonth(), 1);
return [{ json: { report_type: 'monthly', from_date: fmt(firstPrevMonth), to_date: fmt(lastPrevMonth), period_label: `${firstPrevMonth.getFullYear()}-${pad(firstPrevMonth.getMonth() + 1)}` } }];

const vars = (typeof $vars === 'object' && $vars) ? $vars : {};
const base = String(vars.REPORT_APP_BASE_URL || 'https://www.inandoutuae.com').replace(/\/+$/, '');
const token = String(vars.REPORT_API_TOKEN || vars.N8N_REPORT_API_TOKEN || '').trim();
if (!base) throw new Error('REPORT_APP_BASE_URL is missing in n8n Variables.');
if (!token) throw new Error('REPORT_API_TOKEN is missing in n8n Variables.');
const body = {
  report_type: String($json.report_type || 'daily'),
  from_date: String($json.from_date || '').trim(),
  to_date: String($json.to_date || '').trim(),
  date: String($json.to_date || '').trim(),
  save_snapshot: '1',
};
const report = await this.helpers.httpRequest({
  method: 'POST',
  url: base + '/api/reports/daily-operations',
  headers: { 'X-Report-Api-Key': token },
  body,
  json: true,
  timeout: 300000,
});
return [{ json: { ...$json, operations_report: report, operations_report_link: report.share_url || '' } }];

const vars = (typeof $vars === 'object' && $vars) ? $vars : {};
const report = $json.operations_report || {};
const metrics = report.metrics || {};
const money = (value) => Number(value || 0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const number = (value) => Number(value || 0).toLocaleString('en-US');
const type = String($json.report_type || report.operations_type || 'daily');
const title = type === 'monthly' ? '📆 التقرير الشهري لكل الأفرع' : type === 'weekly' ? '📌 التقرير الأسبوعي لكل الأفرع' : '📊 التقرير اليومي لكل الأفرع';
const link = String(report.share_url || $json.operations_report_link || '').trim();
const text = `${title}
📅 الفترة: ${$json.period_label || report.date_label || ''}

🏪 النطاق: كل الأفرع
💰 الإيرادات: ${money(metrics.total_revenue)} AED
🧾 عدد الطلبات: ${number(metrics.total_orders)}
📉 المصروفات: ${money(metrics.total_expenses)} AED
💵 صافي الكاش: ${money(metrics.closing_balance)} AED

📎 التقرير جاهز للفتح مباشرة:
${link || 'REPORT_LINK_NOT_READY'}`;
return [{ json: { ...$json, telegram_text: text, owner_telegram_chat_id: String(vars.REPORT_OWNER_TELEGRAM_CHAT_ID || 'REPLACE_OWNER_TELEGRAM_CHAT_ID') } }];
